    					bpInstance.stock_case_creation_in_progress = false;
                        bpInstance.update();
    					new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().setTradeCaseType(bpInstance.trade_id,'automated'); //MSSCUSTODY-3326 : Add case type as Automated during case creation.
